"""An autogenerated revision imports the modules of the types it renders by path."""

import os
import subprocess
import sys
import tempfile
import textwrap
import unittest
from pathlib import Path

FILES = {
    "pyproject.toml": textwrap.dedent(
        """\
        [tool.ruff.lint]
        select = ["E", "W", "F", "I", "B", "C4", "UP"]

        [tool.ruff.lint.isort]
        known-first-party = ["tgen"]
        """
    ),
    "tgen/__init__.py": "",
    # A column type from another module of the app, rendered by its module path.
    "tgen/types.py": textwrap.dedent(
        """\
        from sqlalchemy.types import UserDefinedType


        class Point(UserDefinedType):
            cache_ok = True

            def __init__(self, dim):
                self.dim = dim

            def get_col_spec(self, **kw):
                return "POINT"
        """
    ),
    "tgen/place/__init__.py": "def init_app(app):\n    pass\n",
    "tgen/place/models.py": textwrap.dedent(
        """\
        from sqlalchemy import CheckConstraint, Integer
        from sqlalchemy.orm import Mapped, mapped_column
        from stk.extensions import Base

        from tgen.types import Point


        class Place(Base):
            __tablename__ = "place"
            id: Mapped[int] = mapped_column(primary_key=True)
            spot = mapped_column(Point(2))
            rank = mapped_column(Integer, CheckConstraint("rank > 0", name="rank"))
        """
    ),
}

# A fresh interpreter: the app's table would otherwise join shared metadata.
SCRIPT = """
import sys
from alembic import command
import tgen.place
from stk.app import Stk
from stk.cli.database import generate_revision
from stk.migrations import build_alembic_config
from stk.settings import TestingConfig

class Config(TestingConfig):
    SECRET_KEY = SECURITY_PASSWORD_SALT = "test"
    SQLALCHEMY_DATABASE_URI = "sqlite+aiosqlite:///" + sys.argv[1]

app = Stk("tgen", config=Config, extensions=[tgen.place])
command.upgrade(build_alembic_config(app, quiet=True), "heads")
print(generate_revision(app, "place", quiet=True).path)
command.upgrade(build_alembic_config(app, quiet=True), "heads")
"""


class RevisionImportsTest(unittest.TestCase):
    def test_revision_imports_app_types_and_passes_ruff(self):
        with tempfile.TemporaryDirectory(prefix="stk-rev-") as root:
            for name, text in FILES.items():
                path = Path(root) / name
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(text)
            result = subprocess.run(
                [sys.executable, "-c", SCRIPT, f"{root}/app.db"],
                cwd=root,
                env={**os.environ, "PYTHONPATH": root},
                capture_output=True,
                text=True,
            )
            self.assertEqual(result.returncode, 0, result.stderr)
            revision = Path(result.stdout.strip().splitlines()[-1]).read_text()
            lint = subprocess.run(
                [sys.executable, "-m", "ruff", "check", "--no-cache", root],
                cwd=root,
                capture_output=True,
                text=True,
            )

        self.assertIn("\nimport tgen.types\n", revision)
        self.assertIn("tgen.types.Point(2)", revision)
        self.assertEqual(lint.returncode, 0, lint.stdout)
        self.assertIn("place.rank: autogenerate leaves out", result.stdout)


if __name__ == "__main__":
    unittest.main()
